// One-off migration tool: targeted, reviewed source edits applied to the
// modules generated by split-legacy.cjs. Every replacement must match exactly
// once (or `all: true`), so a failed match aborts loudly.
//
// usage: node scripts/port/fix-ported.cjs
const fs = require("fs");
const path = require("path");
const root = path.resolve(__dirname, "..", "..");

const edits = {
  "src/render/shape.ts": [
    { find: "                cx = (th + x7) / 2\n", repl: "                var cx: any = (th + x7) / 2\n" },
    { find: /\bstyleTable\b/g, repl: 'warpObj.ctx.styleTable', all: true },
    {
      // custom geometry: replaced by custGeomToSvgPaths (issues #41, #43)
      find: /        var pathLstNode: any = getTextByPathList\(custShapType, \["a:pathLst"\]\);[\s\S]*?            \/\/console\.log\(result\);\n        \}\n/,
      repl: [
        "        // custom geometry (a:custGeom) -> SVG paths, see ./custgeom.ts",
        '        var custFill: any = (!imgFillFlg ? (grndFillFlg ? "url(#linGrd_" + shpId + ")" : fillColor) : "url(#imgPtrn_" + shpId + ")");',
        "        var custPaths: any = custGeomToSvgPaths(custShapType, w, h);",
        "        for (var cp = 0; cp < custPaths.length; cp++) {",
        "            var custPath: any = custPaths[cp];",
        "            result += \"<path d='\" + custPath.d + \"' fill='\" + (custPath.fill ? custFill : \"none\") +",
        "                \"' stroke='\" + ((border === undefined || !custPath.stroke) ? \"none\" : border.color) + \"' stroke-width='\" + ((border === undefined) ? \"\" : border.width) + \"' stroke-dasharray='\" + ((border === undefined) ? \"\" : border.strokeDasharray) + \"' \";",
        '            result += "/>";',
        "        }",
        "",
      ].join("\n"),
    },
    { find: 'import type { WarpObj } from "./context";\n', repl: 'import type { WarpObj } from "./context";\nimport { custGeomToSvgPaths } from "./custgeom";\n' },
  ],
  "src/render/nodes.ts": [
    { find: "        txBoxVal = getTextByPathList(", repl: "        var txBoxVal: any = getTextByPathList(" },
    { find: "    var mediaProcess: any = settings.mediaProcess;", repl: "    var mediaProcess: any = warpObj.ctx.mediaProcess;" },
    { find: "if (vdoNode !== undefined & mediaProcess) {", repl: "if (vdoNode !== undefined && mediaProcess) {" },
    { find: "if (audioNode !== undefined & mediaProcess) {", repl: "if (audioNode !== undefined && mediaProcess) {" },
    { find: "    dgmQuickStyleFileName = warpObj", repl: "    var dgmQuickStyleFileName: any = warpObj" },
    { find: /readXmlFile\(zip, (\w+)\)/g, repl: "zip.xmlFresh($1)", all: true },
    { find: "    var imgArrayBuffer: any = zip.file(imgName).asArrayBuffer();", repl: "    var imgArrayBuffer: any = zip.bytes(imgName);\n    if (imgArrayBuffer === null) {\n        warpObj.ctx.warn(\"Missing image part: \" + imgName);\n        return \"\";\n    }" },
    { find: "                uInt8Array = zip.file(vdoFile).asArrayBuffer();", repl: "                uInt8Array = zip.bytes(vdoFile);" },
    { find: "                vdoBlob = URL.createObjectURL(blob);\n                mediaSupportFlag = true;", repl: "                vdoBlob = warpObj.ctx.createObjectUrl(blob);\n                mediaSupportFlag = vdoBlob !== \"\";" },
    { find: "            uInt8ArrayAudio = zip.file(audioFile).asArrayBuffer();\n            blobAudio = new Blob([uInt8ArrayAudio]);\n            audioBlob = URL.createObjectURL(blobAudio);", repl: "            uInt8ArrayAudio = zip.bytes(audioFile);\n            blobAudio = new Blob([uInt8ArrayAudio], { type: getMimeType(audioFileExt) });\n            audioBlob = warpObj.ctx.createObjectUrl(blobAudio);" },
    { find: 'import type { WarpObj } from "./context";\n', repl: 'import type { WarpObj } from "./context";\nimport { genTable } from "./table";\n' },
  ],
  "src/render/color.ts": [{ find: "{ h: cocacl_h,", repl: "{ h: cacl_h," }],
  "src/render/geometry.ts": [
    { find: "    cy = outerRadius;//Math.max(innerRadius, outerRadius),                    // center y\n    notches = points,", repl: "    var cy: any = outerRadius;//Math.max(innerRadius, outerRadius),                    // center y\n    var notches: any = points," },
  ],
  "src/render/table.ts": [
    { find: /\bstyleTable\b/g, repl: "warpObj.ctx.styleTable", all: true },
    { find: /(^|[^.\w])tableStyles\b/g, repl: "$1warpObj.ctx.tableStyles", all: true },
  ],
  "src/render/text.ts": [
    { find: /\bstyleTable\b/g, repl: "warpObj.ctx.styleTable", all: true },
    { find: /parseInt\((\w+), "px"\)/g, repl: "parseInt($1)", all: true },
    { find: "var isIE11: any = !!window.MSInputMethodContext && !!document.documentMode;", repl: "var isIE11: any = false; // IE11 is no longer supported" },
    {
      find: /var txt_obj: any = \$\(prgr_text\)\s*\.css\(\{[^}]*\}\)\s*\.appendTo\(\$\('body'\)\);\s*total_text_len \+= txt_obj\.outerWidth\(\);\s*txt_obj\.remove\(\);/g,
      repl: "total_text_len += warpObj.ctx.measureHtmlWidth(prgr_text);",
      all: true,
    },
    { find: 'import { dingbat_unicode } from "../dingbat";', repl: 'import { dingbatToUnicode } from "../dingbat";\n\n// v1 kept this as an implicit global shared between genTextBody and genSpanElement.\nlet is_first_br: any = false;' },
    { find: "    var imgArrayBuffer: any = warpObj[\"zip\"].file(imgPath).asArrayBuffer();", repl: "    var imgArrayBuffer: any = warpObj[\"zip\"].bytes(imgPath);" },
  ],
  "src/render/fill.ts": [
    { find: "        var imgArrayBuffer: any = warpObj[\"zip\"].file(imgPath).asArrayBuffer();", repl: "        var imgArrayBuffer: any = warpObj[\"zip\"].bytes(imgPath);\n        if (imgArrayBuffer === null) return undefined;" },
  ],
};

let failed = false;
for (const [file, list] of Object.entries(edits)) {
  const p = path.join(root, file);
  let text = fs.readFileSync(p, "utf8");
  for (const e of list) {
    if (typeof e.find === "string") {
      const n = text.split(e.find).length - 1;
      if (n !== 1) {
        console.error(`${file}: expected 1 match, got ${n}: ${e.find.slice(0, 80)}`);
        failed = true;
        continue;
      }
      text = text.replace(e.find, () => e.repl);
    } else {
      const matches = text.match(e.find);
      if (!matches || (!e.all && matches.length !== 1)) {
        console.error(`${file}: regex matched ${matches ? matches.length : 0}x: ${e.find}`);
        failed = true;
        continue;
      }
      text = text.replace(e.find, e.repl);
    }
  }
  fs.writeFileSync(p, text);
}
if (failed) process.exit(1);
console.log("ok");
